const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

const btc_nodes = require('btc_nodes')
const peers_inspector = require('peers_inspector')
const activity_inspector = require('activity_inspector')

module.exports = more_menu

async function more_menu(opts = {}, protocol) {
  const { sdb } = await get(opts.sid)
  const { drive } = sdb
  const on = { style: inject, data: ondata, icons: iconject }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'open' })
  shadow.innerHTML = `
    <main class="more-page">
      <section class="menu-view">
        <header class="page-header">
          <p class="eyebrow">Advanced inspector</p>
          <h1>More</h1>
          <p>Detailed, read-only information from your Bitcoin and Lightning services.</p>
        </header>
        <div class="option-list"></div>
      </section>
      <section class="detail-view hidden"></section>
    </main>
    <style></style>
  `

  const style = shadow.querySelector('style')
  const menuView = shadow.querySelector('.menu-view')
  const detailView = shadow.querySelector('.detail-view')
  const optionList = shadow.querySelector('.option-list')
  const listeners = new Set()
  const sendUp = protocol ? protocol(receiveFromParent) : null
  const subs = await sdb.watch(onbatch)

  const childProtocol = function (receiveFromChild) {
    listeners.add(receiveFromChild)
    return function (message) {
      if (typeof sendUp === 'function') sendUp({ from: 'more_menu', ...message })
    }
  }

  const views = {
    nodes: await btc_nodes(subs[0], childProtocol, { onClose: closeDetail }),
    peers: await peers_inspector(subs[1], childProtocol, { onClose: closeDetail }),
    activity: await activity_inspector(subs[2], childProtocol, { onClose: closeDetail })
  }

  Object.values(views).forEach(function (view) {
    view.classList.add('inspector-child')
    view.style.display = 'none'
    detailView.appendChild(view)
  })

  shadow.addEventListener('click', function (event) {
    const option = event.target.closest('[data-view]')
    if (option) openDetail(option.dataset.view)
  })

  el.open = function () { closeDetail() }
  ondata()
  return el

  function openDetail(name) {
    const view = views[name]
    if (!view) return
    Object.values(views).forEach(function (child) { child.style.display = 'none' })
    view.style.display = ''
    menuView.classList.add('hidden')
    detailView.classList.remove('hidden')
    if (view.open) view.open()
  }

  function closeDetail() {
    detailView.classList.add('hidden')
    menuView.classList.remove('hidden')
    Object.values(views).forEach(function (child) { child.style.display = 'none' })
  }

  function receiveFromParent(message) {
    listeners.forEach(function (listener) { listener(message) })
  }

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(path => drive.get(path).then(file => file.raw)))
      const func = on[type] || fail
      await func(data, type)
    }
  }

  function inject(data) { style.textContent = data[0] }
  function iconject() { ondata() }
  function ondata() {
    optionList.innerHTML = `
      <button class="option-card" data-view="nodes">
        <span class="option-icon nodes-icon">⌁</span>
        <span class="option-copy"><strong>Nodes</strong><small>Inspect your Bitcoin and Lightning services</small></span>
        <span class="chevron">›</span>
      </button>
      <button class="option-card" data-view="peers">
        <span class="option-icon peers-icon">↔</span>
        <span class="option-copy"><strong>Peers</strong><small>View and troubleshoot Lightning connections</small></span>
        <span class="chevron">›</span>
      </button>
      <button class="option-card" data-view="activity">
        <span class="option-icon activity-icon">≡</span>
        <span class="option-copy"><strong>Activity</strong><small>Review backend requests, responses, and errors</small></span>
        <span class="chevron">›</span>
      </button>
    `
  }
  function fail(data, type) { throw new Error('invalid message', { cause: { data, type } }) }
}

function fallback_module() {
  return {
    api: fallback_instance,
    _: { btc_nodes: { $: '' }, peers_inspector: { $: '' }, activity_inspector: { $: '' } }
  }

  function fallback_instance(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}
    const btcNodes = { mapping: { icons: 'icons', style: 'style', data: 'data' }, 0: {} }
    const peersInspector = { mapping: { icons: 'icons', style: 'style', data: 'data' }, 0: {} }
    const activityInspector = { mapping: { icons: 'icons', style: 'style', data: 'data' }, 0: {} }
    return {
      drive: {
        'icons/': { 'x.svg': { '$ref': 'x.svg' }, 'dot.svg': { '$ref': 'dot.svg' } },
        'style/': { 'style.css': { '$ref': 'more_menu.css' } },
        'data/': { 'opts.json': { raw: opts || {} } }
      },
      _: { btc_nodes: btcNodes, peers_inspector: peersInspector, activity_inspector: activityInspector }
    }
  }
}
